package got.world.genlayer; public class GOTGenLayerNarrowRivers extends GOTGenLayer {private final int maxRange;public GOTGenLayerNarrowRivers(long s,GOTGenLayer p,int r){super(s);gotParent=p;maxRange=r;}public int[] getInts(int x,int z,int w,int h){int[] p=gotParent.getInts(x-maxRange,z-maxRange,w+maxRange*2,h+maxRange*2),o=new int[w*h];int pw=w+maxRange*2;for(int dz=0;dz<h;dz++)for(int dx=0;dx<w;dx++){int best=-1;outer:for(int r=0;r<=maxRange;r++)for(int zz=-r;zz<=r;zz++)for(int xx=-r;xx<=r;xx++)if(p[dx+maxRange+xx+(dz+maxRange+zz)*pw]>=0){best=1;break outer;}o[dx+dz*w]=best;}return o;}}